create table if not exists public.career_players (
  id          uuid        primary key default gen_random_uuid(),
  player_name text        not null unique,
  nationality text        not null,
  position    text        not null,
  created_at  timestamptz not null default now()
);
alter table public.career_players enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'career_players' and policyname = 'Public read-only') then
    create policy "Public read-only" on public.career_players for select to anon, authenticated using (true);
  end if;
end $$;
create table if not exists public.career_seasons (
  id           uuid        primary key default gen_random_uuid(),
  player_id    uuid        not null references public.career_players(id) on delete cascade,
  season       text        not null,
  club         text        not null,
  goals        integer     not null,
  assists      integer     not null,
  appearances  integer     not null,
  market_value integer     not null,
  sort_order   smallint    not null,
  created_at   timestamptz not null default now()
);
alter table public.career_seasons enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'career_seasons' and policyname = 'Public read-only') then
    create policy "Public read-only" on public.career_seasons for select to anon, authenticated using (true);
  end if;
end $$;
create index if not exists career_seasons_player_id_idx on public.career_seasons (player_id);
on conflict (id) do update set
  player_name = excluded.player_name,
  nationality = excluded.nationality,
  position    = excluded.position;
on conflict (id) do update set
  player_id    = excluded.player_id,
  season       = excluded.season,
  club         = excluded.club,
  goals        = excluded.goals,
  assists      = excluded.assists,
  appearances  = excluded.appearances,
  market_value = excluded.market_value,
  sort_order   = excluded.sort_order;
